pub fn dt_named_p(name: Str, ds: Dts) -> bool {
    any_p(lambda1(move |d: &'static Dt| {
        let tagcase_ = d;
        match *tagcase_ {
            Dt::Dt(n, ps, vs) => {
                string_eq_p(n, name)
            }
        }
    }), ds)
}

/// A datatype, its parameters and variants, as a list of one, or none.
pub fn find_family(mut name: Str, mut ds: Dts) -> List<&'static Dt> {
    loop {
        if null_p(ds) {
            return nil();
        } else if {
            let tagcase_ = car(ds);
            match *tagcase_ {
                Dt::Dt(n, ps, vs) => {
                    string_eq_p(n, name)
                }
            }
        } {
            return cons(car(ds), nil());
        } else {
            ds = cdr(ds);
            continue;
        }
    }
}

/// A type abbreviation, its parameters and what it stands for, as a list
/// of one, or none.
pub fn find_alias(mut name: Str, mut r#as: Aliases) -> List<&'static Alias> {
    loop {
        if null_p(r#as) {
            return nil();
        } else {
            let tagcase_ = car(r#as);
            match *tagcase_ {
                Alias::Alias(n, ps, t) => {
                    if string_eq_p(n, name) {
                        return cons(car(r#as), nil());
                    } else {
                        r#as = cdr(r#as);
                        continue;
                    }
                }
            }
        }
    }
}

/// `tvars`: the type variables in scope.
pub fn parse_type(mut v: &'static Cv, mut tvars: Strings, mut t: &'static Sexp) -> &'static Ty {
    loop {
        let tagcase_ = t;
        match *tagcase_ {
            Sexp::Sym(s) => {
                if string_eq_p(s, str_lit("i64")) {
                    return ty_i64();
                } else if string_eq_p(s, str_lit("int")) {
                    return ty_int();
                } else if string_eq_p(s, str_lit("bool")) {
                    return ty_bool();
                } else if string_eq_p(s, str_lit("char")) {
                    return ty_char();
                } else if string_eq_p(s, str_lit("unit")) {
                    return ty_unit();
                } else if string_eq_p(s, str_lit("string")) {
                    return ty_string();
                } else if string_eq_p(s, str_lit("void")) {
                    return ty_void();
                } else if string_member_p(s, tvars) {
                    return ty_var(s);
                } else if dt_named_p(s, cv_dts(v)) {
                    let tagcase_ = car(find_family(s, cv_dts(v)));
                    match *tagcase_ {
                        Dt::Dt(n, ps, vs) => {
                            if null_p(ps) {
                                return ty_data(s, nil());
                            } else {
                                return refuse(v, string_append(str_lit("a type with parameters, given none: "), s));
                            }
                        }
                    }
                } else {
                    let found = find_alias(s, cv_aliases(v));
                    if null_p(found) {
                        return refuse(v, string_append(str_lit("no type is named "), s));
                    } else {
                        let tagcase_ = car(found);
                        match *tagcase_ {
                            Alias::Alias(n, ps, body) => {
                                if null_p(ps) {
                                    t = body;
                                    continue;
                                } else {
                                    return refuse(v, string_append(str_lit("a type with parameters, given none: "), s));
                                }
                            }
                        }
                    }
                }
            }
            Sexp::Lst(xs, src_file, src_line, src_pos) => {
                if sym_is_p(car(xs), str_lit("listof")) {
                    return ty_list(parse_type(v, tvars, second(xs)), parse_region(v, tvars, third(xs)));
                } else if sym_is_p(car(xs), str_lit("flatarrayof")) {
                    if sym_is_p(second(xs), str_lit("i64")) {
                        return ty_flat(ty_i64(), parse_mutable_region(v, tvars, third(xs)));
                    } else {
                        return refuse(v, string_append(str_lit("KFX-0's flat arrays are of i64: "), show_sexp(t)));
                    }
                } else if sym_is_p(car(xs), str_lit("ref")) {
                    return ty_ref(parse_type(v, tvars, second(xs)), parse_mutable_region(v, tvars, third(xs)));
                } else if sym_is_p(car(xs), str_lit("subr")) {
                    return ty_proc(parse_effect(v, tvars, second(xs)), parse_types(v, tvars, items(third(xs))), parse_type(v, tvars, fourth(xs)));
                } else if {
                    let tagcase_ = car(xs);
                    match *tagcase_ {
                        Sexp::Sym(n) => {
                            (dt_named_p(n, cv_dts(v)) || not(null_p(find_alias(n, cv_aliases(v)))))
                        }
                        _ => {
                            let other = tagcase_;
                            false
                        }
                    }
                } {
                    return parse_application(v, tvars, name_of(v, car(xs)), cdr(xs));
                } else {
                    return refuse(v, string_append(str_lit("a type KFX does not have: "), show_sexp(t)));
                }
            }
            _ => {
                let other = tagcase_;
                return refuse(v, string_append(str_lit("a type KFX does not have: "), show_sexp(t)));
            }
        }
    }
}

pub fn parse_types(v: &'static Cv, tvars: Strings, ts: Sexps) -> Tys {
    map(lambda1(move |t: &'static Sexp| {
        parse_type(v, tvars, t)
    }), ts)
}

/// A family's arguments, each read as its parameter's kind says: a
/// region for a name beginning `'`, a type otherwise.
pub fn parse_arguments(v: &'static Cv, tvars: Strings, params: Strings, args: Sexps) -> Tys {
    if (null_p(params) && null_p(args)) {
        nil()
    } else if (null_p(params) || null_p(args)) {
        refuse(v, str_lit("a type given the wrong number of arguments"))
    } else {
        cons(if char_eq_p(string_ref_i64(car(params), 0i64), '\'') {
            parse_region(v, tvars, car(args))
        } else {
            parse_type(v, tvars, car(args))
        }, parse_arguments(v, tvars, cdr(params), cdr(args)))
    }
}

/// `(name arg ...)`: a datatype with parameters, applied; or a type
/// abbreviation with them, what it stands for with its arguments.
pub fn parse_application(v: &'static Cv, tvars: Strings, name: Str, args: Sexps) -> &'static Ty {
    let found = find_family(name, cv_dts(v));
    if not(null_p(found)) {
        let tagcase_ = car(found);
        match *tagcase_ {
            Dt::Dt(n, ps, vs) => {
                ty_data(name, parse_arguments(v, tvars, ps, args))
            }
        }
    } else {
        let tagcase_ = car(find_alias(name, cv_aliases(v)));
        match *tagcase_ {
            Alias::Alias(n, ps, body) => {
                substitute(ps, parse_arguments(v, tvars, ps, args), parse_type(v, ps, body))
            }
        }
    }
}

/// A family's parameters, from its head `(name (p kind) ...)`: a type's
/// named as written, a region's with `'` first; none for a bare name.
pub fn family_params(v: &'static Cv, head: &'static Sexp) -> Strings {
    let tagcase_ = head;
    match *tagcase_ {
        Sexp::Lst(xs, src_file, src_line, src_pos) => {
            map(lambda1(move |b: &'static Sexp| {
                let b = items(b);
                if sym_is_p(second(b), str_lit("type")) {
                    name_of(v, car(b))
                } else if sym_is_p(second(b), str_lit("region")) {
                    string_append(str_lit("'"), name_of(v, car(b)))
                } else {
                    refuse(v, string_append(str_lit("a family over a kind KFX does not have: "), show_sexp(lst(b, str_lit(""), 0i64, 0i64))))
                }
            }), cdr(xs))
        }
        _ => {
            let other = tagcase_;
            nil()
        }
    }
}

/// A definition's type's variables: a poly at its top, over types, and
/// regions, whose names begin with `'`.
pub fn poly_binders(v: &'static Cv, t: &'static Sexp) -> Strings {
    if head_is_p(t, str_lit("poly")) {
        map(lambda1(move |b: &'static Sexp| {
            let b = items(b);
            if not(i64_eq(size(b), 2i64)) {
                refuse(v, string_append(str_lit("a binder KFX-0 does not have (distinct regions are to come): "), show_sexp(lst(b, str_lit(""), 0i64, 0i64))))
            } else if sym_is_p(second(b), str_lit("type")) {
                name_of(v, car(b))
            } else if sym_is_p(second(b), str_lit("region")) {
                string_append(str_lit("'"), name_of(v, car(b)))
            } else {
                refuse(v, string_append(str_lit("KFX's poly is over types and regions: "), show_sexp(lst(b, str_lit(""), 0i64, 0i64))))
            }
        }), items(second(items(t))))
    } else {
        nil()
    }
}

pub fn parse_scheme(v: &'static Cv, t: &'static Sexp) -> &'static Scheme {
    let tvars = poly_binders(v, t);
    scheme(tvars, parse_type(v, tvars, if head_is_p(t, str_lit("poly")) {
        third(items(t))
    } else {
        t
    }))
}

pub fn show_ty(s: &'static St, t: &'static Ty) -> Str {
    let tagcase_ = walk(s, t);
    match *tagcase_ {
        Ty::TyI64() => {
            str_lit("i64")
        }
        Ty::TyInt() => {
            str_lit("int")
        }
        Ty::TyBool() => {
            str_lit("bool")
        }
        Ty::TyChar() => {
            str_lit("char")
        }
        Ty::TyUnit() => {
            str_lit("unit")
        }
        Ty::TyString() => {
            str_lit("string")
        }
        Ty::TyVoid() => {
            str_lit("void")
        }
        Ty::TyList(e, r) => {
            string_append(str_lit("(listof "), string_append(show_ty(s, e), string_append(str_lit(" "), string_append(show_ty(s, r), str_lit(")")))))
        }
        Ty::TyData(d, args) => {
            if null_p(args) {
                d
            } else {
                string_append(str_lit("("), string_append(d, string_append(str_lit(" "), string_append(show_tys(s, args), str_lit(")")))))
            }
        }
        Ty::TyFlat(e, r) => {
            string_append(str_lit("(flatarrayof "), string_append(show_ty(s, e), string_append(str_lit(" "), string_append(show_ty(s, r), str_lit(")")))))
        }
        Ty::TyRef(e, r) => {
            string_append(str_lit("(ref "), string_append(show_ty(s, e), string_append(str_lit(" "), string_append(show_ty(s, r), str_lit(")")))))
        }
        Ty::TyRconst(n) => {
            n
        }
        Ty::TyProc(es, ps, r) => {
            string_append(str_lit("(subr "), string_append(show_effs(es), string_append(str_lit(" ("), string_append(show_tys(s, ps), string_append(str_lit(") "), string_append(show_ty(s, r), str_lit(")")))))))
        }
        Ty::TyVar(n) => {
            n
        }
        Ty::TyMeta(k) => {
            string_append(str_lit("?"), i64_to_string(k))
        }
    }
}

pub fn show_tys(s: &'static St, ts: Tys) -> Str {
    if null_p(ts) {
        str_lit("")
    } else if null_p(cdr(ts)) {
        show_ty(s, car(ts))
    } else {
        string_append(show_ty(s, car(ts)), string_append(str_lit(" "), show_tys(s, cdr(ts))))
    }
}

/// `t`, its inference variable replaced by its solution, if it has one.
pub fn walk(mut s: &'static St, mut t: &'static Ty) -> &'static Ty {
    loop {
        let tagcase_ = t;
        match *tagcase_ {
            Ty::TyMeta(k) => {
                let tagcase_ = s;
                match *tagcase_ {
                    St::St(subst, next, fs) => {
                        let found = lookup_meta(k, subst);
                        if null_p(found) {
                            return t;
                        } else {
                            t = car(found);
                            continue;
                        }
                    }
                }
            }
            _ => {
                let other = tagcase_;
                return t;
            }
        }
    }
}

pub fn lookup_meta(mut k: i64, mut subst: Sbs) -> Tys {
    loop {
        if null_p(subst) {
            return nil();
        } else {
            let tagcase_ = car(subst);
            match *tagcase_ {
                Sb::Sb(j, t) => {
                    if i64_eq(j, k) {
                        return cons(t, nil());
                    } else {
                        subst = cdr(subst);
                        continue;
                    }
                }
            }
        }
    }
}

/// Whether `t` has an inference variable not solved yet.
pub fn has_meta_p(s: &'static St, t: &'static Ty) -> bool {
    let tagcase_ = walk(s, t);
    match *tagcase_ {
        Ty::TyMeta(k) => {
            true
        }
        Ty::TyList(e, r) => {
            (has_meta_p(s, e) || has_meta_p(s, r))
        }
        Ty::TyFlat(e, r) => {
            (has_meta_p(s, e) || has_meta_p(s, r))
        }
        Ty::TyData(d, args) => {
            any_p(lambda1(move |x: &'static Ty| {
                has_meta_p(s, x)
            }), args)
        }
        Ty::TyRef(e, r) => {
            (has_meta_p(s, e) || has_meta_p(s, r))
        }
        Ty::TyProc(es, ps, r) => {
            (has_meta_p(s, r) || any_p(lambda1(move |p: &'static Ty| {
                has_meta_p(s, p)
            }), ps))
        }
        _ => {
            let other = tagcase_;
            false
        }
    }
}

/// A new inference variable.
pub fn fresh(s: &'static St) -> &'static Res {
    let tagcase_ = s;
    match *tagcase_ {
        St::St(subst, next, fs) => {
            res(ty_meta(next), nil(), st(subst, i64_plus(next, 1i64), fs))
        }
    }
}

pub fn note_fact(s: &'static St, file: Str, pos: i64, what: Str) -> &'static St {
    let tagcase_ = s;
    match *tagcase_ {
        St::St(subst, next, fs) => {
            st(subst, next, cons(fact(file, pos, what), fs))
        }
    }
}

pub fn st_facts(s: &'static St) -> Facts {
    let tagcase_ = s;
    match *tagcase_ {
        St::St(subst, next, fs) => {
            fs
        }
    }
}

pub fn solve(s: &'static St, k: i64, t: &'static Ty) -> &'static St {
    let tagcase_ = s;
    match *tagcase_ {
        St::St(subst, next, fs) => {
            st(cons(sb(k, t), subst), next, fs)
        }
    }
}

pub fn occurs_p(s: &'static St, k: i64, t: &'static Ty) -> bool {
    let tagcase_ = walk(s, t);
    match *tagcase_ {
        Ty::TyMeta(j) => {
            i64_eq(j, k)
        }
        Ty::TyList(e, r) => {
            (occurs_p(s, k, e) || occurs_p(s, k, r))
        }
        Ty::TyFlat(e, r) => {
            (occurs_p(s, k, e) || occurs_p(s, k, r))
        }
        Ty::TyData(d, args) => {
            any_p(lambda1(move |x: &'static Ty| {
                occurs_p(s, k, x)
            }), args)
        }
        Ty::TyRef(e, r) => {
            (occurs_p(s, k, e) || occurs_p(s, k, r))
        }
        Ty::TyProc(es, ps, r) => {
            (occurs_p(s, k, r) || any_p(lambda1(move |p: &'static Ty| {
                occurs_p(s, k, p)
            }), ps))
        }
        _ => {
            let other = tagcase_;
            false
        }
    }
}

pub fn same_base_p(a: &'static Ty, e: &'static Ty) -> bool {
    let tagcase_ = a;
    match *tagcase_ {
        Ty::TyI64() => {
            let tagcase_ = e;
            match *tagcase_ {
                Ty::TyI64() => {
                    true
                }
                _ => {
                    let other = tagcase_;
                    false
                }
            }
        }
        Ty::TyInt() => {
            let tagcase_ = e;
            match *tagcase_ {
                Ty::TyInt() => {
                    true
                }
                _ => {
                    let other = tagcase_;
                    false
                }
            }
        }
        Ty::TyBool() => {
            let tagcase_ = e;
            match *tagcase_ {
                Ty::TyBool() => {
                    true
                }
                _ => {
                    let other = tagcase_;
                    false
                }
            }
        }
        Ty::TyChar() => {
            let tagcase_ = e;
            match *tagcase_ {
                Ty::TyChar() => {
                    true
                }
                _ => {
                    let other = tagcase_;
                    false
                }
            }
        }
        Ty::TyUnit() => {
            let tagcase_ = e;
            match *tagcase_ {
                Ty::TyUnit() => {
                    true
                }
                _ => {
                    let other = tagcase_;
                    false
                }
            }
        }
        Ty::TyString() => {
            let tagcase_ = e;
            match *tagcase_ {
                Ty::TyString() => {
                    true
                }
                _ => {
                    let other = tagcase_;
                    false
                }
            }
        }
        _ => {
            let other = tagcase_;
            false
        }
    }
}

/// That a value of type `actual` may stand where `expected` is: the two
/// the same, inference variables solved to make them so, but for
/// `void`, which fits anything, and a procedure, whose latent effect
/// may be within the one expected.
pub fn fits(v: &'static Cv, s: &'static St, actual: &'static Ty, expected: &'static Ty) -> &'static St {
    let (a, e) = (walk(s, actual), walk(s, expected));
    let tagcase_ = a;
    match *tagcase_ {
        Ty::TyVoid() => {
            s
        }
        Ty::TyMeta(k) => {
            let tagcase_ = e;
            match *tagcase_ {
                Ty::TyMeta(j) => {
                    if i64_eq(j, k) {
                        s
                    } else {
                        solve(s, k, e)
                    }
                }
                _ => {
                    let other = tagcase_;
                    if occurs_p(s, k, e) {
                        mismatch(v, s, a, e)
                    } else {
                        solve(s, k, e)
                    }
                }
            }
        }
        _ => {
            let other = tagcase_;
            let tagcase_ = e;
            match *tagcase_ {
                Ty::TyMeta(j) => {
                    if occurs_p(s, j, a) {
                        mismatch(v, s, a, e)
                    } else {
                        solve(s, j, a)
                    }
                }
                _ => {
                    let other = tagcase_;
                    fits_shapes(v, s, a, e)
                }
            }
        }
    }
}

pub fn fits_shapes(v: &'static Cv, s: &'static St, a: &'static Ty, e: &'static Ty) -> &'static St {
    let tagcase_ = a;
    match *tagcase_ {
        Ty::TyList(x, xr) => {
            let tagcase_ = e;
            match *tagcase_ {
                Ty::TyList(y, yr) => {
                    fits(v, fits(v, s, x, y), xr, yr)
                }
                _ => {
                    let other = tagcase_;
                    mismatch(v, s, a, e)
                }
            }
        }
        Ty::TyFlat(x, xr) => {
            let tagcase_ = e;
            match *tagcase_ {
                Ty::TyFlat(y, yr) => {
                    fits(v, fits(v, s, x, y), xr, yr)
                }
                _ => {
                    let other = tagcase_;
                    mismatch(v, s, a, e)
                }
            }
        }
        Ty::TyRef(x, xr) => {
            let tagcase_ = e;
            match *tagcase_ {
                Ty::TyRef(y, yr) => {
                    fits(v, fits(v, s, x, y), xr, yr)
                }
                _ => {
                    let other = tagcase_;
                    mismatch(v, s, a, e)
                }
            }
        }
        Ty::TyRconst(x) => {
            let tagcase_ = e;
            match *tagcase_ {
                Ty::TyRconst(y) => {
                    if string_eq_p(x, y) {
                        s
                    } else {
                        mismatch(v, s, a, e)
                    }
                }
                _ => {
                    let other = tagcase_;
                    mismatch(v, s, a, e)
                }
            }
        }
        Ty::TyData(x, xs) => {
            let tagcase_ = e;
            match *tagcase_ {
                Ty::TyData(y, ys) => {
                    if (string_eq_p(x, y) && i64_eq(size(xs), size(ys))) {
                        fits_all(v, s, xs, ys)
                    } else {
                        mismatch(v, s, a, e)
                    }
                }
                _ => {
                    let other = tagcase_;
                    mismatch(v, s, a, e)
                }
            }
        }
        Ty::TyVar(x) => {
            let tagcase_ = e;
            match *tagcase_ {
                Ty::TyVar(y) => {
                    if string_eq_p(x, y) {
                        s
                    } else {
                        mismatch(v, s, a, e)
                    }
                }
                _ => {
                    let other = tagcase_;
                    mismatch(v, s, a, e)
                }
            }
        }
        Ty::TyProc(aes, aps, ar) => {
            let tagcase_ = e;
            match *tagcase_ {
                Ty::TyProc(ees, eps, er) => {
                    if not(i64_eq(size(aps), size(eps))) {
                        mismatch(v, s, a, e)
                    } else if not(effs_within_p(aes, ees)) {
                        mismatch(v, s, a, e)
                    } else {
                        fits(v, fits_all(v, s, eps, aps), ar, er)
                    }
                }
                _ => {
                    let other = tagcase_;
                    mismatch(v, s, a, e)
                }
            }
        }
        _ => {
            let other = tagcase_;
            if same_base_p(a, e) {
                s
            } else {
                mismatch(v, s, a, e)
            }
        }
    }
}

/// Parameters: each expected parameter's type stands for the actual's.
pub fn fits_all(mut v: &'static Cv, mut s: &'static St, mut actuals: Tys, mut expecteds: Tys) -> &'static St {
    loop {
        if null_p(actuals) {
            return s;
        } else {
            (s, actuals, expecteds) = (fits(v, s, car(actuals), car(expecteds)), cdr(actuals), cdr(expecteds));
            continue;
        }
    }
}

pub fn mismatch(v: &'static Cv, s: &'static St, a: &'static Ty, e: &'static Ty) -> &'static St {
    refuse(v, string_append(str_lit("a "), string_append(show_ty(s, a), string_append(str_lit(" is here, where a "), string_append(show_ty(s, e), str_lit(" is expected"))))))
}

// A scheme's instance: each variable an inference variable; those for
// regions are kept, so that a call's effect can name the regions found.
pub enum Inst {
    Inst(&'static Ty, &'static St, List<i64>),
}

pub fn inst(f0: &'static Ty, f1: &'static St, f2: List<i64>) -> &'static Inst {
    alloc(Inst::Inst(f0, f1, f2))
}

pub fn instantiate(s: &'static St, sc: &'static Scheme) -> &'static Inst {
    let tagcase_ = sc;
    match *tagcase_ {
        Scheme::Scheme(tvars, t) => {
            instantiate_vars(s, tvars, t, nil())
        }
    }
}

pub fn instantiate_vars(s: &'static St, tvars: Strings, t: &'static Ty, regions: List<i64>) -> &'static Inst {
    if null_p(tvars) {
        inst(t, s, regions)
    } else {
        let tagcase_ = fresh(s);
        match *tagcase_ {
            Res::Res(m, es, s) => {
                let tagcase_ = m;
                match *tagcase_ {
                    Ty::TyMeta(k) => {
                        instantiate_vars(s, cdr(tvars), replace_var(car(tvars), m, t), if char_eq_p(string_ref_i64(car(tvars), 0i64), '\'') {
                            cons(k, regions)
                        } else {
                            regions
                        })
                    }
                    _ => {
                        let other = tagcase_;
                        inst(t, s, regions)
                    }
                }
            }
        }
    }
}

// The names in scope
/// The innermost binding of `name`, as a list of one, or none.
pub fn find_bind(mut name: Str, mut bs: Binds) -> Binds {
    loop {
        if null_p(bs) {
            return nil();
        } else {
            let tagcase_ = car(bs);
            match *tagcase_ {
                Bind::Bind(n, sc, r#where) => {
                    if string_eq_p(n, name) {
                        return cons(car(bs), nil());
                    } else {
                        bs = cdr(bs);
                        continue;
                    }
                }
            }
        }
    }
}

/// FX-26's keywords, which name nothing (fixpt's top.rs, KEYWORDS).
pub fn keyword_p(name: Str) -> bool {
    (string_eq_p(name, str_lit("lambda")) || string_eq_p(name, str_lit("plambda")) || string_eq_p(name, str_lit("proj")) || string_eq_p(name, str_lit("if")) || string_eq_p(name, str_lit("letrec")) || string_eq_p(name, str_lit("let")) || string_eq_p(name, str_lit("begin")) || string_eq_p(name, str_lit("define")) || string_eq_p(name, str_lit("define*")) || string_eq_p(name, str_lit("define-type")) || string_eq_p(name, str_lit("define-generative")) || string_eq_p(name, str_lit("subr")) || string_eq_p(name, str_lit("poly")) || string_eq_p(name, str_lit("ref")) || string_eq_p(name, str_lit("pairof")) || string_eq_p(name, str_lit("dletrec")) || string_eq_p(name, str_lit("void")) || string_eq_p(name, str_lit("pure")) || string_eq_p(name, str_lit("maxeff")) || string_eq_p(name, str_lit("read")) || string_eq_p(name, str_lit("write")) || string_eq_p(name, str_lit("alloc")) || string_eq_p(name, str_lit("goto")) || string_eq_p(name, str_lit("comefrom")) || string_eq_p(name, str_lit("region")) || string_eq_p(name, str_lit("effect")) || string_eq_p(name, str_lit("type")) || string_eq_p(name, str_lit("prompt")) || string_eq_p(name, str_lit("prompt-tag")) || string_eq_p(name, str_lit("composable")) || string_eq_p(name, str_lit("mark-key")) || string_eq_p(name, str_lit("listof")) || string_eq_p(name, str_lit("cond")) || string_eq_p(name, str_lit("case")) || string_eq_p(name, str_lit("else")) || string_eq_p(name, str_lit("and")) || string_eq_p(name, str_lit("or")) || string_eq_p(name, str_lit("let*")) || string_eq_p(name, str_lit("define-effect")) || string_eq_p(name, str_lit("module-parameters")) || string_eq_p(name, str_lit("the")) || string_eq_p(name, str_lit("bloblet")) || string_eq_p(name, str_lit("fields")) || string_eq_p(name, str_lit("frozen")) || string_eq_p(name, str_lit("arrayof")) || string_eq_p(name, str_lit("icell")) || string_eq_p(name, str_lit("await")) || string_eq_p(name, str_lit("define-rec")) || string_eq_p(name, str_lit("letrena")) || string_eq_p(name, str_lit("letreap")) || string_eq_p(name, str_lit("rlambda")) || string_eq_p(name, str_lit("quote")) || string_eq_p(name, str_lit("productof")) || string_eq_p(name, str_lit("sumof")) || string_eq_p(name, str_lit("product")) || string_eq_p(name, str_lit("extract")) || string_eq_p(name, str_lit("sum")) || string_eq_p(name, str_lit("tagcase")) || string_eq_p(name, str_lit("module")) || string_eq_p(name, str_lit("moduleof")) || string_eq_p(name, str_lit("with")) || string_eq_p(name, str_lit("select")) || string_eq_p(name, str_lit("load-module")) || string_eq_p(name, str_lit("define-datatype")) || string_eq_p(name, str_lit("make-bloblet")) || string_eq_p(name, str_lit("bloblet-ref")) || string_eq_p(name, str_lit("bloblet-set!")) || string_eq_p(name, str_lit("bloblet-freeze")) || string_eq_p(name, str_lit("bloblet-byte")) || string_eq_p(name, str_lit("bloblet-set-byte!")) || string_eq_p(name, str_lit("bloblet-bytes")) || string_eq_p(name, str_lit("rmake-bloblet")) || string_eq_p(name, str_lit("dlambda")) || string_eq_p(name, str_lit("=>")) || string_eq_p(name, str_lit("blobref-at")) || string_eq_p(name, str_lit("blobref+")) || string_eq_p(name, str_lit("blobref-owner")) || string_eq_p(name, str_lit("blobref-offset")) || string_eq_p(name, str_lit("blobref-get")) || string_eq_p(name, str_lit("blobref-set!")) || string_eq_p(name, str_lit("blobref-index")) || string_eq_p(name, str_lit("blobref-variant!")))
}

pub fn bind_onto(mut xs: Binds, mut ys: Binds) -> Binds {
    loop {
        if null_p(xs) {
            return ys;
        } else {
            (xs, ys) = (cdr(xs), cons(car(xs), ys));
            continue;
        }
    }
}

/// `v`, checking a list that began at `line` of `file`.
pub fn near(v: &'static Cv, file: Str, line: i64) -> &'static Cv {
    if i64_eq(line, 0i64) {
        v
    } else {
        let tagcase_ = v;
        match *tagcase_ {
            Cv::Cv(bs, ds, r#as, es, here, group, f, l, fs) => {
                cv(bs, ds, r#as, es, here, group, file, line, fs)
            }
        }
    }
}

pub fn with_binds(v: &'static Cv, more: Binds) -> &'static Cv {
    let tagcase_ = v;
    match *tagcase_ {
        Cv::Cv(bs, ds, r#as, es, here, group, file, line, fs) => {
            cv(bind_onto(more, bs), ds, r#as, es, here, group, file, line, fs)
        }
    }
}

/// A local may be named by a keyword, as FX-26 has it; it may not then be
/// called, since FX-26 reads such a call as its form (`synth-call`).
pub fn local(v: &'static Cv, name: Str, t: &'static Ty) -> &'static Bind {
    bind(name, scheme(nil(), t), str_lit("local"))
}

// Expressions
pub fn with_effs(r: &'static Res, es: Strings) -> &'static Res {
    let tagcase_ = r;
    match *tagcase_ {
        Res::Res(t, es0, s) => {
            res(t, effs_union(es, es0), s)
        }
    }
}

pub fn proc_type_p(s: &'static St, t: &'static Ty) -> bool {
    let tagcase_ = walk(s, t);
    match *tagcase_ {
        Ty::TyProc(es, ps, r) => {
            true
        }
        _ => {
            let other = tagcase_;
            false
        }
    }
}

/// What naming a name does: a global is read, and a global procedure
/// named as a value may be called from anywhere, so may loop.
pub fn naming_effs(s: &'static St, name: Str, r#where: Str, t: &'static Ty) -> Strings {
    if not(string_eq_p(r#where, str_lit("global"))) {
        nil()
    } else if proc_type_p(s, t) {
        cons(str_lit("spin"), cons(string_append(str_lit("g:"), name), nil()))
    } else {
        cons(string_append(str_lit("g:"), name), nil())
    }
}

pub fn void_p(s: &'static St, t: &'static Ty) -> bool {
    let tagcase_ = walk(s, t);
    match *tagcase_ {
        Ty::TyVoid() => {
            true
        }
        _ => {
            let other = tagcase_;
            false
        }
    }
}

/// What the branches after one of type `t` are checked against: the type
/// expected, if known, else `t`, unless that is `void`, which says
/// nothing.
pub fn next_expected(s: &'static St, t: &'static Ty, expected: Tys) -> Tys {
    if not(null_p(expected)) {
        expected
    } else if void_p(s, t) {
        nil()
    } else {
        cons(t, nil())
    }
}

/// The type of branches, the first of type `t` and the rest of `rest`.
pub fn joined(s: &'static St, t: &'static Ty, rest: &'static Ty, expected: Tys) -> &'static Ty {
    if not(null_p(expected)) {
        car(expected)
    } else if void_p(s, t) {
        rest
    } else {
        t
    }
}

pub fn region_string(s: &'static St, r: &'static Ty) -> Str {
    let tagcase_ = walk(s, r);
    match *tagcase_ {
        Ty::TyRconst(n) => {
            n
        }
        Ty::TyVar(n) => {
            n
        }
        Ty::TyMeta(k) => {
            meta_name(k)
        }
        _ => {
            let other = tagcase_;
            str_lit("?")
        }
    }
}

/// A region, solved: one no argument nor expected type said is `acyclic`,
/// as FX-26's fresh region for it, masked where it is not seen, is pure.
pub fn region_of(v: &'static Cv, s: &'static St, r: &'static Ty) -> &'static Res {
    let tagcase_ = walk(s, r);
    match *tagcase_ {
        Ty::TyMeta(k) => {
            res(ty_rconst(str_lit("acyclic")), nil(), solve(s, k, ty_rconst(str_lit("acyclic"))))
        }
        _ => {
            let other = tagcase_;
            res(other, nil(), s)
        }
    }
}

/// A call's latent effect, its regions' inference variables replaced by
/// the regions the arguments and the type expected found, or `acyclic`.
pub fn name_regions(v: &'static Cv, s: &'static St, es: Strings, regions: List<i64>) -> &'static Res {
    if null_p(regions) {
        res(ty_unit(), es, s)
    } else {
        let tagcase_ = region_of(v, s, ty_meta(car(regions)));
        match *tagcase_ {
            Res::Res(r, rn, s) => {
                name_regions(v, s, rename_atoms(es, meta_name(car(regions)), region_string(s, r)), cdr(regions))
            }
        }
    }
}

pub fn control_form_p(h: Str) -> bool {
    (string_eq_p(h, str_lit("if")) || string_eq_p(h, str_lit("cond")) || string_eq_p(h, str_lit("case")) || string_eq_p(h, str_lit("tagcase")) || string_eq_p(h, str_lit("let")) || string_eq_p(h, str_lit("let*")) || string_eq_p(h, str_lit("begin")) || string_eq_p(h, str_lit("letrec")))
}

pub fn all_chars_p(xs: Sexps) -> bool {
    not(any_p(lambda1(move |x: &'static Sexp| {
        let tagcase_ = x;
        match *tagcase_ {
            Sexp::Chr(c) => {
                false
            }
            _ => {
                let other = tagcase_;
                true
            }
        }
    }), xs))
}

pub fn bind_fields(v: &'static Cv, names: Sexps, types: Tys) -> Binds {
    if null_p(names) {
        nil()
    } else {
        cons(local(v, name_of(v, car(names)), car(types)), bind_fields(v, cdr(names), cdr(types)))
    }
}

pub fn bind_params(v: &'static Cv, params: Sexps, types: Tys) -> Binds {
    if null_p(params) {
        nil()
    } else {
        cons(local(v, param_name(car(params)), car(types)), bind_params(v, cdr(params), cdr(types)))
    }
}

pub fn find_dt(mut d: Str, mut ds: Dts) -> List<Variants> {
    loop {
        if null_p(ds) {
            return nil();
        } else {
            let tagcase_ = car(ds);
            match *tagcase_ {
                Dt::Dt(n, ps, vs) => {
                    if string_eq_p(n, d) {
                        return cons(vs, nil());
                    } else {
                        ds = cdr(ds);
                        continue;
                    }
                }
            }
        }
    }
}

/// A datatype's parameters.
pub fn family_of(v: &'static Cv, d: Str) -> Strings {
    let found = find_family(d, cv_dts(v));
    if null_p(found) {
        nil()
    } else {
        let tagcase_ = car(found);
        match *tagcase_ {
            Dt::Dt(n, ps, vs) => {
                ps
            }
        }
    }
}

/// Variants whose fields' types are of the datatype's parameters, at
/// `args`.
pub fn instantiate_variants(params: Strings, args: Tys, vs: Variants) -> Variants {
    map(lambda1(move |x: &'static Variant| {
        let tagcase_ = x;
        match *tagcase_ {
            Variant::Variant(tag, fields) => {
                variant(tag, map(lambda1(move |f: &'static Ty| {
                    substitute(params, args, f)
                }), fields))
            }
        }
    }), vs)
}

pub fn variants_of(v: &'static Cv, d: Str) -> Variants {
    let found = find_dt(d, cv_dts(v));
    if null_p(found) {
        refuse(v, string_append(str_lit("no datatype is named "), d))
    } else {
        car(found)
    }
}

pub fn variant_fields(mut v: &'static Cv, mut d: Str, mut tag: Str, mut vs: Variants) -> Tys {
    loop {
        if null_p(vs) {
            return refuse(v, string_append(tag, string_append(str_lit(" is no tag of "), string_append(d, str_lit(", or has an arm already")))));
        } else {
            let tagcase_ = car(vs);
            match *tagcase_ {
                Variant::Variant(t, fields) => {
                    if string_eq_p(t, tag) {
                        return fields;
                    } else {
                        vs = cdr(vs);
                        continue;
                    }
                }
            }
        }
    }
}

pub fn without_tag(tag: Str, vs: Variants) -> Variants {
    if null_p(vs) {
        nil()
    } else {
        let tagcase_ = car(vs);
        match *tagcase_ {
            Variant::Variant(t, fields) => {
                if string_eq_p(t, tag) {
                    cdr(vs)
                } else {
                    cons(car(vs), without_tag(tag, cdr(vs)))
                }
            }
        }
    }
}

pub fn synth(v: &'static Cv, s: &'static St, e: &'static Sexp) -> &'static Res {
    let tagcase_ = e;
    match *tagcase_ {
        Sexp::Num(k, num_file, num_pos) => {
            res(ty_int(), nil(), note_fact(s, num_file, num_pos, str_lit("int")))
        }
        Sexp::Chr(c) => {
            res(ty_char(), nil(), s)
        }
        Sexp::Str(x) => {
            res(ty_string(), nil(), s)
        }
        Sexp::Sym(name) => {
            synth_name(v, s, name)
        }
        Sexp::Lst(xs, src_file, src_line, src_pos) => {
            let v = near(v, src_file, src_line);
            let tagcase_ = car(xs);
            match *tagcase_ {
                Sexp::Sym(h) => {
                    synth_form(v, s, e, h, cdr(xs))
                }
                _ => {
                    let head = tagcase_;
                    synth_call_of(v, s, synth(v, s, head), cdr(xs), nil(), nil(), cons(str_lit("spin"), nil()))
                }
            }
        }
    }
}

pub fn synth_name(v: &'static Cv, s: &'static St, name: Str) -> &'static Res {
    if (string_eq_p(name, str_lit("#t")) || string_eq_p(name, str_lit("#f"))) {
        res(ty_bool(), nil(), s)
    } else if string_eq_p(name, str_lit("#u")) {
        res(ty_unit(), nil(), s)
    } else {
        let found = find_bind(name, cv_binds(v));
        if null_p(found) {
            refuse(v, string_append(str_lit("nothing is named "), name))
        } else {
            let tagcase_ = car(found);
            match *tagcase_ {
                Bind::Bind(n, sc, r#where) => {
                    let tagcase_ = instantiate(s, sc);
                    match *tagcase_ {
                        Inst::Inst(t, s, regions) => {
                            res(t, naming_effs(s, name, r#where, t), s)
                        }
                    }
                }
            }
        }
    }
}

pub fn check(v: &'static Cv, s: &'static St, e: &'static Sexp, expected: &'static Ty) -> &'static Res {
    let x = walk(s, expected);
    let tagcase_ = e;
    match *tagcase_ {
        Sexp::Num(k, num_file, num_pos) => {
            // A literal is an `i64` where one is expected, and otherwise an
            // `int`, as in FX-26: an inference variable it meets is solved
            // to `int`.
            let tagcase_ = x;
            match *tagcase_ {
                Ty::TyI64() => {
                    res(x, nil(), s)
                }
                Ty::TyInt() => {
                    res(x, nil(), note_fact(s, num_file, num_pos, str_lit("int")))
                }
                Ty::TyMeta(m) => {
                    res(ty_int(), nil(), note_fact(solve(s, m, ty_int()), num_file, num_pos, str_lit("int")))
                }
                _ => {
                    let other = tagcase_;
                    refuse(v, string_append(str_lit("a literal is here, where a "), string_append(show_ty(s, x), str_lit(" is expected"))))
                }
            }
        }
        Sexp::Lst(xs, src_file, src_line, src_pos) => {
            let v = near(v, src_file, src_line);
            let tagcase_ = car(xs);
            match *tagcase_ {
                Sexp::Sym(h) => {
                    check_form(v, s, e, h, cdr(xs), x)
                }
                _ => {
                    let other = tagcase_;
                    check_by_synth(v, s, e, x)
                }
            }
        }
        Sexp::Sym(name) => {
            if string_eq_p(name, str_lit("nil")) {
                let tagcase_ = x;
                match *tagcase_ {
                    Ty::TyList(el, r) => {
                        res(x, nil(), s)
                    }
                    _ => {
                        let other = tagcase_;
                        check_by_synth(v, s, e, x)
                    }
                }
            } else {
                check_by_synth(v, s, e, x)
            }
        }
        _ => {
            let other = tagcase_;
            check_by_synth(v, s, e, x)
        }
    }
}

pub fn check_by_synth(v: &'static Cv, s: &'static St, e: &'static Sexp, expected: &'static Ty) -> &'static Res {
    let tagcase_ = synth(v, s, e);
    match *tagcase_ {
        Res::Res(t, es, s) => {
            res(expected, es, fits(v, s, t, expected))
        }
    }
}

/// A body: each expression but the last for its effect, the last
/// checked against `expected` if it has one type in it, else found.
pub fn body(v: &'static Cv, s: &'static St, es: Sexps, expected: Tys) -> &'static Res {
    if null_p(cdr(es)) {
        if null_p(expected) {
            synth(v, s, car(es))
        } else {
            check(v, s, car(es), car(expected))
        }
    } else {
        let tagcase_ = synth_any(v, s, car(es));
        match *tagcase_ {
            Res::Res(t, es0, s) => {
                with_effs(body(v, s, cdr(es), expected), es0)
            }
        }
    }
}

/// An expression whose value is dropped: a string is a comment.
pub fn synth_any(v: &'static Cv, s: &'static St, e: &'static Sexp) -> &'static Res {
    let tagcase_ = e;
    match *tagcase_ {
        Sexp::Str(x) => {
            res(ty_unit(), nil(), s)
        }
        _ => {
            let other = tagcase_;
            synth(v, s, e)
        }
    }
}

pub fn synth_form(v: &'static Cv, s: &'static St, e: &'static Sexp, h: Str, xs: Sexps) -> &'static Res {
    if string_eq_p(h, str_lit("the")) {
        check(v, s, second(xs), parse_type(v, nil(), car(xs)))
    } else if string_eq_p(h, str_lit("lambda")) {
        synth_lambda(v, s, items(car(xs)), cdr(xs))
    } else if string_eq_p(h, str_lit("list")) {
        if null_p(xs) {
            let tagcase_ = fresh(s);
            match *tagcase_ {
                Res::Res(m, es, s) => {
                    res(ty_list(m, ty_rconst(str_lit("acyclic"))), nil(), s)
                }
            }
        } else {
            let tagcase_ = synth(v, s, car(xs));
            match *tagcase_ {
                Res::Res(t, es0, s) => {
                    with_effs(check(v, s, e, ty_list(t, ty_rconst(str_lit("acyclic")))), es0)
                }
            }
        }
    } else if control_form_p(h) {
        body_form(v, s, h, xs, nil())
    } else if string_eq_p(h, str_lit("and")) {
        bools(v, s, xs)
    } else if string_eq_p(h, str_lit("or")) {
        bools(v, s, xs)
    } else {
        synth_call(v, s, h, xs, nil())
    }
}

pub fn check_form(v: &'static Cv, s: &'static St, e: &'static Sexp, h: Str, xs: Sexps, expected: &'static Ty) -> &'static Res {
    if control_form_p(h) {
        body_form(v, s, h, xs, cons(expected, nil()))
    } else if (string_eq_p(h, str_lit("lambda")) && proc_type_p(s, expected)) {
        check_lambda(v, s, items(car(xs)), cdr(xs), walk(s, expected))
    } else if (string_eq_p(h, str_lit("list")) && {
        let tagcase_ = expected;
        match *tagcase_ {
            Ty::TyList(el, r) => {
                true
            }
            _ => {
                let other = tagcase_;
                false
            }
        }
    }) {
        let tagcase_ = expected;
        match *tagcase_ {
            Ty::TyList(el, r) => {
                let tagcase_ = elements(v, s, xs, el);
                match *tagcase_ {
                    Res::Res(u, es, s) => {
                        let tagcase_ = region_of(v, s, r);
                        match *tagcase_ {
                            Res::Res(rr, rn, s) => {
                                res(expected, effs_union(cons(string_append(str_lit("alloc:"), region_string(s, rr)), nil()), es), s)
                            }
                        }
                    }
                }
            }
            _ => {
                let other = tagcase_;
                check_by_synth(v, s, e, expected)
            }
        }
    } else if (string_eq_p(h, str_lit("the")) || string_eq_p(h, str_lit("and")) || string_eq_p(h, str_lit("or")) || string_eq_p(h, str_lit("lambda")) || string_eq_p(h, str_lit("list"))) {
        check_by_synth(v, s, e, expected)
    } else {
        synth_call(v, s, h, xs, cons(expected, nil()))
    }
}

/// A list's elements, each checked as `el`: their effect, and the state,
/// which carries their facts.
pub fn elements(v: &'static Cv, s: &'static St, xs: Sexps, el: &'static Ty) -> &'static Res {
    if null_p(xs) {
        res(el, nil(), s)
    } else {
        let tagcase_ = check(v, s, car(xs), el);
        match *tagcase_ {
            Res::Res(t, es, s) => {
                with_effs(elements(v, s, cdr(xs), el), es)
            }
        }
    }
}

pub fn bools(v: &'static Cv, s: &'static St, xs: Sexps) -> &'static Res {
    if null_p(xs) {
        res(ty_bool(), nil(), s)
    } else {
        let tagcase_ = check(v, s, car(xs), ty_bool());
        match *tagcase_ {
            Res::Res(t, es, s) => {
                with_effs(bools(v, s, cdr(xs)), es)
            }
        }
    }
}

/// `if`, `cond`, `case`, `tagcase`, `let`, `let*` and `begin`: forms
/// whose last parts give the value; `expected` is the type, if known.
pub fn body_form(v: &'static Cv, s: &'static St, h: Str, xs: Sexps, expected: Tys) -> &'static Res {
    if string_eq_p(h, str_lit("if")) {
        let tagcase_ = check(v, s, car(xs), ty_bool());
        match *tagcase_ {
            Res::Res(t, es, s) => {
                with_effs(arms(v, s, cdr(xs), expected), es)
            }
        }
    } else if string_eq_p(h, str_lit("begin")) {
        body(v, s, xs, expected)
    } else if string_eq_p(h, str_lit("let")) {
        let_values(v, s, items(car(xs)), cdr(xs), expected, nil(), false)
    } else if string_eq_p(h, str_lit("let*")) {
        let_values(v, s, items(car(xs)), cdr(xs), expected, nil(), true)
    } else if string_eq_p(h, str_lit("letrec")) {
        letrec_form(v, s, items(car(xs)), cdr(xs), expected)
    } else if string_eq_p(h, str_lit("cond")) {
        cond_clauses(v, s, xs, expected)
    } else if string_eq_p(h, str_lit("case")) {
        let tagcase_ = check(v, s, car(xs), ty_char());
        match *tagcase_ {
            Res::Res(t, es, s) => {
                with_effs(case_arms(v, s, cdr(xs), expected), es)
            }
        }
    } else {
        let tagcase_ = synth(v, s, car(xs));
        match *tagcase_ {
            Res::Res(t, es, s) => {
                let tagcase_ = walk(s, t);
                match *tagcase_ {
                    Ty::TyData(d, args) => {
                        with_effs(tag_arms(v, s, walk(s, t), cdr(xs), instantiate_variants(family_of(v, d), args, variants_of(v, d)), expected), es)
                    }
                    _ => {
                        let other = tagcase_;
                        refuse(v, string_append(str_lit("tagcase of a "), string_append(show_ty(s, t), str_lit(", no datatype"))))
                    }
                }
            }
        }
    }
}

/// Branches of one type: the first found, if none is expected, and the
/// rest checked against it.
pub fn arms(v: &'static Cv, s: &'static St, branches: Sexps, expected: Tys) -> &'static Res {
    let tagcase_ = body(v, s, cons(car(branches), nil()), expected);
    match *tagcase_ {
        Res::Res(t, es, s) => {
            if null_p(cdr(branches)) {
                res(t, es, s)
            } else {
                let tagcase_ = arms(v, s, cdr(branches), next_expected(s, t, expected));
                match *tagcase_ {
                    Res::Res(t2, es2, s) => {
                        res(joined(s, t, t2, expected), effs_union(es, es2), s)
                    }
                }
            }
        }
    }
}

pub fn cond_clauses(v: &'static Cv, s: &'static St, clauses: Sexps, expected: Tys) -> &'static Res {
    let clause = items(car(clauses));
    if sym_is_p(car(clause), str_lit("else")) {
        if null_p(cdr(clauses)) {
            body(v, s, cdr(clause), expected)
        } else {
            refuse(v, str_lit("a cond's else is its last clause"))
        }
    } else {
        if null_p(cdr(clauses)) {
            refuse(v, str_lit("a cond needs an else: FX has no unspecified value"))
        } else {
            let tagcase_ = check(v, s, car(clause), ty_bool());
            match *tagcase_ {
                Res::Res(t0, es0, s) => {
                    let tagcase_ = body(v, s, cdr(clause), expected);
                    match *tagcase_ {
                        Res::Res(t, es, s) => {
                            let tagcase_ = cond_clauses(v, s, cdr(clauses), next_expected(s, t, expected));
                            match *tagcase_ {
                                Res::Res(t2, es2, s) => {
                                    res(joined(s, t, t2, expected), effs_union(es0, effs_union(es, es2)), s)
                                }
                            }
                        }
                    }
                }
            }
        }
    }
}

pub fn case_arms(v: &'static Cv, s: &'static St, cases: Sexps, expected: Tys) -> &'static Res {
    let arm = items(car(cases));
    if sym_is_p(car(arm), str_lit("else")) {
        if null_p(cdr(cases)) {
            body(v, s, cdr(arm), expected)
        } else {
            refuse(v, str_lit("a case's else is its last arm"))
        }
    } else if null_p(cdr(cases)) {
        refuse(v, str_lit("a case needs an else: FX has no unspecified value"))
    } else if not(all_chars_p(items(car(arm)))) {
        refuse(v, str_lit("KFX's case is on characters: FX-26's compares integers as ints"))
    } else {
        let tagcase_ = body(v, s, cdr(arm), expected);
        match *tagcase_ {
            Res::Res(t, es, s) => {
                let tagcase_ = case_arms(v, s, cdr(cases), next_expected(s, t, expected));
                match *tagcase_ {
                    Res::Res(t2, es2, s) => {
                        res(joined(s, t, t2, expected), effs_union(es, es2), s)
                    }
                }
            }
        }
    }
}

/// A tagcase's arms; `vs` are the variants no arm has taken yet.
pub fn tag_arms(v: &'static Cv, s: &'static St, whole: &'static Ty, tagged: Sexps, vs: Variants, expected: Tys) -> &'static Res {
    if null_p(tagged) {
        if null_p(vs) {
            if null_p(expected) {
                refuse(v, str_lit("a tagcase with no arms"))
            } else {
                res(car(expected), nil(), s)
            }
        } else {
            refuse(v, string_append(str_lit("a tagcase of a "), string_append(show_ty(s, whole), str_lit(" with no else, and no arm for each tag"))))
        }
    } else {
        let arm = items(car(tagged));
        let tag = name_of(v, car(arm));
        if string_eq_p(tag, str_lit("else")) {
            if null_p(cdr(tagged)) {
                body(with_binds(v, cons(local(v, name_of(v, second(arm)), whole), nil())), s, cdr(cdr(arm)), expected)
            } else {
                refuse(v, str_lit("a tagcase's else is its last arm"))
            }
        } else {
            let fields = variant_fields(v, show_ty(s, whole), tag, vs);
            let names = items(second(arm));
            if not(i64_eq(size(names), size(fields))) {
                refuse(v, string_append(str_lit("the arm for "), string_append(tag, str_lit(" names the wrong number of fields"))))
            } else {
                let tagcase_ = body(with_binds(v, bind_fields(v, names, fields)), s, cdr(cdr(arm)), expected);
                match *tagcase_ {
                    Res::Res(t, es, s) => {
                        let tagcase_ = tag_arms(v, s, whole, cdr(tagged), without_tag(tag, vs), next_expected(s, t, expected));
                        match *tagcase_ {
                            Res::Res(t2, es2, s) => {
                                res(joined(s, t, t2, expected), effs_union(es, es2), s)
                            }
                        }
                    }
                }
            }
        }
    }
}

/// A `let`'s or `let*`'s bindings, then its body. `bound`: those made
/// so far, which a `let*`'s next binding sees and a `let`'s does not.
pub fn let_values(v: &'static Cv, s: &'static St, bindings: Sexps, forms: Sexps, expected: Tys, bound: Binds, sequential: bool) -> &'static Res {
    if null_p(bindings) {
        body(with_binds(v, bound), s, forms, expected)
    } else {
        let b = items(car(bindings));
        let sees = if sequential {
            with_binds(v, bound)
        } else {
            v
        };
        let tagcase_ = synth(sees, s, second(b));
        match *tagcase_ {
            Res::Res(t, es, s) => {
                with_effs(let_values(v, s, cdr(bindings), forms, expected, cons(local(v, name_of(v, car(b)), t), bound), sequential), es)
            }
        }
    }
}

/// `(letrec ((f T lambda) ...) body ...)`: each procedure's type written,
/// every one in scope in each lambda and in the body.
pub fn letrec_form(v: &'static Cv, s: &'static St, bindings: Sexps, forms: Sexps, expected: Tys) -> &'static Res {
    let w = with_binds(v, map(lambda1(move |b: &'static Sexp| {
        let ys = items(b);
        local(v, name_of(v, car(ys)), parse_type(v, nil(), second(ys)))
    }), bindings));
    let tagcase_ = letrec_lambdas(w, s, bindings);
    match *tagcase_ {
        Res::Res(u, es, s) => {
            body(w, s, forms, expected)
        }
    }
}

pub fn letrec_lambdas(v: &'static Cv, s: &'static St, bindings: Sexps) -> &'static Res {
    if null_p(bindings) {
        res(ty_unit(), nil(), s)
    } else {
        let ys = items(car(bindings));
        if not(head_is_p(third(ys), str_lit("lambda"))) {
            refuse(v, str_lit("a letrec binds only lambdas"))
        } else {
            let tagcase_ = check(v, s, third(ys), parse_type(v, nil(), second(ys)));
            match *tagcase_ {
                Res::Res(t, es, s) => {
                    letrec_lambdas(v, s, cdr(bindings))
                }
            }
        }
    }
}

/// A lambda with nothing expected: its parameters' types written.
pub fn synth_lambda(v: &'static Cv, s: &'static St, params: Sexps, forms: Sexps) -> &'static Res {
    let types = map(lambda1(move |p: &'static Sexp| {
        let tagcase_ = p;
        match *tagcase_ {
            Sexp::Lst(pt, src_file, src_line, src_pos) => {
                parse_type(v, nil(), second(pt))
            }
            _ => {
                let other = tagcase_;
                refuse(v, string_append(str_lit("a lambda with nothing expected needs its parameters' types: "), show_sexp(other)))
            }
        }
    }), params);
    let tagcase_ = body(with_binds(v, bind_params(v, params, types)), s, forms, nil());
    match *tagcase_ {
        Res::Res(r, es, s) => {
            res(ty_proc(es, types, r), nil(), s)
        }
    }
}

pub fn check_lambda(v: &'static Cv, s: &'static St, params: Sexps, forms: Sexps, expected: &'static Ty) -> &'static Res {
    let tagcase_ = expected;
    match *tagcase_ {
        Ty::TyProc(ees, eps, er) => {
            if not(i64_eq(size(params), size(eps))) {
                refuse(v, str_lit("a lambda of the wrong number of parameters"))
            } else {
                let s = check_written_params(v, s, params, eps);
                let tagcase_ = body(with_binds(v, bind_params(v, params, eps)), s, forms, cons(er, nil()));
                match *tagcase_ {
                    Res::Res(r, es, s) => {
                        if effs_within_p(es, ees) {
                            res(expected, nil(), s)
                        } else {
                            refuse(v, string_append(str_lit("a lambda whose effect "), string_append(show_effs(es), string_append(str_lit(" is not within "), show_effs(ees)))))
                        }
                    }
                }
            }
        }
        _ => {
            let other = tagcase_;
            refuse(v, str_lit("a lambda where no procedure is expected"))
        }
    }
}

/// A lambda's body's effect, the body checked against the type `t`'s
/// parameters and result, but not its effect: what `define*` finds.
pub fn lambda_effects(v: &'static Cv, s: &'static St, params: Sexps, forms: Sexps, t: &'static Ty) -> &'static Res {
    let tagcase_ = t;
    match *tagcase_ {
        Ty::TyProc(ees, eps, er) => {
            if not(i64_eq(size(params), size(eps))) {
                refuse(v, str_lit("a lambda of the wrong number of parameters"))
            } else {
                body(with_binds(v, bind_params(v, params, eps)), check_written_params(v, s, params, eps), forms, cons(er, nil()))
            }
        }
        _ => {
            let other = tagcase_;
            refuse(v, str_lit("a lambda where no procedure is expected"))
        }
    }
}

/// A parameter written `(x T)` must be of the type expected. One written
/// `x` must have its type known already, from the arguments before the
/// lambda: rustc, which checks a call's arguments in order, finds a
/// closure's parameter types no other way.
pub fn check_written_params(mut v: &'static Cv, mut s: &'static St, mut params: Sexps, mut types: Tys) -> &'static St {
    loop {
        if null_p(params) {
            return s;
        } else {
            (s, params, types) = ({
                let tagcase_ = car(params);
                match *tagcase_ {
                    Sexp::Lst(pt, src_file, src_line, src_pos) => {
                        fits(v, s, car(types), parse_type(v, nil(), second(pt)))
                    }
                    _ => {
                        let other = tagcase_;
                        if has_meta_p(s, car(types)) {
                            refuse(v, string_append(str_lit("the type of the lambda's parameter "), string_append(show_sexp(other), str_lit(" is not known from the arguments before it: write it as (x T)"))))
                        } else {
                            s
                        }
                    }
                }
            }, cdr(params), cdr(types));
            continue;
        }
    }
}

/// A call of a name: a procedure in this group is `spin`, one that is a
/// local's value is a call of a procedure not known, so `spin` too.
pub fn synth_call(v: &'static Cv, s: &'static St, h: Str, args: Sexps, expected: Tys) -> &'static Res {
    let found = find_bind(h, cv_binds(v));
    if keyword_p(h) {
        refuse(v, string_append(str_lit("("), string_append(h, str_lit(" ...) is FX-26's form, which KFX does not have, or a call of a local named by that keyword"))))
    } else if null_p(found) {
        refuse(v, string_append(str_lit("nothing is named "), h))
    } else {
        let tagcase_ = car(found);
        match *tagcase_ {
            Bind::Bind(n, sc, r#where) => {
                let tagcase_ = instantiate(s, sc);
                match *tagcase_ {
                    Inst::Inst(t, s, regions) => {
                        synth_call_of(v, s, res(t, nil(), s), args, regions, expected, effs_union(if string_eq_p(r#where, str_lit("global")) {
                            cons(string_append(str_lit("g:"), h), nil())
                        } else {
                            nil()
                        }, if (string_eq_p(r#where, str_lit("local")) || string_member_p(h, cv_group(v))) {
                            cons(str_lit("spin"), nil())
                        } else {
                            nil()
                        }))
                    }
                }
            }
        }
    }
}

/// A call of the procedure `callee` is: its result fitted to the type
/// `expected`, if one is, then its arguments checked against its
/// parameters, in order; its effect, the callee's latent effect, the
/// arguments' and `more`. In order, not lambdas last as FX-26 does,
/// since rustc finds a closure's parameter types only from what comes
/// before it: see `check-written-params`.
pub fn synth_call_of(v: &'static Cv, s: &'static St, callee: &'static Res, args: Sexps, regions: List<i64>, expected: Tys, more: Strings) -> &'static Res {
    let tagcase_ = callee;
    match *tagcase_ {
        Res::Res(t, es0, s) => {
            let tagcase_ = walk(s, t);
            match *tagcase_ {
                Ty::TyProc(latent, ps, r) => {
                    if not(i64_eq(size(ps), size(args))) {
                        refuse(v, string_append(str_lit("a call of the wrong number of arguments: "), show_sexps(args)))
                    } else {
                        let tagcase_ = call_args(v, if null_p(expected) {
                            s
                        } else {
                            fits(v, s, r, car(expected))
                        }, args, ps);
                        match *tagcase_ {
                            Res::Res(u, es1, s) => {
                                let tagcase_ = name_regions(v, s, latent, regions);
                                match *tagcase_ {
                                    Res::Res(u, named, s) => {
                                        res(r, effs_union(named, effs_union(more, effs_union(es0, es1))), s)
                                    }
                                }
                            }
                        }
                    }
                }
                _ => {
                    let other = tagcase_;
                    refuse(v, string_append(str_lit("a call of a "), string_append(show_ty(s, t), str_lit(", no procedure"))))
                }
            }
        }
    }
}

pub fn call_args(v: &'static Cv, s: &'static St, args: Sexps, ps: Tys) -> &'static Res {
    if null_p(args) {
        res(ty_unit(), nil(), s)
    } else {
        let tagcase_ = check(v, s, car(args), car(ps));
        match *tagcase_ {
            Res::Res(t, es, s) => {
                with_effs(call_args(v, s, cdr(args), cdr(ps)), es)
            }
        }
    }
}

